#+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
# This is the SINGLE accessor for the Exudyn version.
#
# Details:  The version is written by tools/issueTracker/issueTracker.py - the micro number is
#           DERIVED from the count of resolved issues - and everything else (versionName.txt,
#           src/Autogenerated/versionCpp.cpp, the version line in README.rst and
#           docs/RST/Exudyn.rst, trackerlog.{tex,rst,html}) is generated from it. So this file is
#           the only thing that has to know where it lives.
#
#           Used from very different working directories: setup.py exec()s it from the repository
#           root, the six generators import it from src/pythonGenerator/, and conf.py exec()s it
#           from the root as well. It therefore anchors on the REPOSITORY ROOT rather than on the
#           current directory.
#
#           Previously this tried four relative paths in sequence (../../../, ../../, ../, ./) and
#           fell back to the literal string 'unknown' when all four missed. That fallback is the
#           real defect: 'unknown' is not a version, setuptools rejects it much later with an
#           InvalidVersion whose message names neither this file nor version.txt, and a generator
#           run would happily stamp 'unknown' into generated sources. Missing the version file is
#           now a hard, named error (revision plan step 28).
#
# Author:   Johannes Gerstmayr
# Date:     2026-09-12 (rewritten)
# Copyright:This file is part of Exudyn. Exudyn is free software: see 'LICENSE.txt'
#
#+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

import os

#the version file, relative to the repository root
versionFileRelativePath = 'version.txt'

#files that identify the repository root; both must be present, so that a stray version.txt
#somewhere above the repository cannot be mistaken for it
rootMarkers = ['pyproject.toml', versionFileRelativePath]


#%%******************************************************************************************************
def GetRepositoryRoot():
    """Absolute path of the repository root, found by walking upwards. Starts at this file when
    it is imported normally, and at the current directory when it is exec()ed (setup.py, conf.py),
    where __file__ is the executing script rather than this one."""

    startDirectories = []
    if '__file__' in globals():
        startDirectories.append(os.path.dirname(os.path.abspath(__file__)))
    startDirectories.append(os.path.abspath(os.getcwd()))

    for startDirectory in startDirectories:
        directory = startDirectory
        while True:
            if all([os.path.isfile(os.path.join(directory, marker)) for marker in rootMarkers]):
                return directory

            parentDirectory = os.path.dirname(directory)
            if parentDirectory == directory: #reached the filesystem root
                break
            directory = parentDirectory

    raise RuntimeError(
        'exudynVersion.py: could not locate the Exudyn repository root. Searched upwards from '
        + ' and from '.join(startDirectories) + ' for a directory containing '
        + ' and '.join(rootMarkers) + '. Run setup.py from the repository root, and the '
        'generators from src/pythonGenerator/.')


#%%******************************************************************************************************
def GetExudynVersionString():
    """The version string, e.g. '1.11.40.dev1'. Raises if the version file is missing: an Exudyn
    with no version is never what the caller wanted."""

    versionFile = os.path.join(GetRepositoryRoot(), versionFileRelativePath)

    with open(versionFile, 'r', encoding='utf8') as file:
        version = file.read().strip()

    if version == '':
        raise RuntimeError('exudynVersion.py: ' + versionFile + ' is empty; it is written by '
                           'tools/issueTracker/issueTracker.py - never by hand')

    return version


exudynVersionString = GetExudynVersionString()
